import { IconArrowForward, IconArrowBack } from "@airbus/icons";
import { IconButton } from "../IconButton";
import { svgColor, svgUri } from "../../helpers";
import { StyleFn } from "..";

export const Pagination: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const { root, _ghost, _primary, _secondary, _small } = IconButton(
    theme,
    mode,
  );
  const bgSvgColor = color.border.accent.default[mode];

  return {
    root: {
      display: "flex",
      alignItems: "center",
    },
    legend: {
      flex: 1,
      fontSize: font.size.xsmall,
      color: color.text.neutral.strong[mode],
    },
    nav: {
      display: "flex",
      // The item immediately before Next should not add extra right spacing.
      "& > *:nth-last-child(2)": {
        marginRight: 0,
      },
    },
    // class for rowsperpage and goto
    side: {
      display: "flex",
      fontSize: `${font.size.small}`, // "0.875rem",
      justifyContent: "space-between",
      alignItems: "center",
      fontWeight: font.weight.bold,
      // increase specficity of row input to take width of the content, as ds-select has 100% width
      "& $side_input": {
        width: "auto",
        paddingRight: size.spacing[48],
      },
      "& $side_right_width": {
        minWidth: size.spacing[80],
      },
    },
    side_right: {
      marginLeft: size.spacing[32],
    },
    side_left: {
      marginRight: size.spacing[32],
    },
    side_input: {},
    side_label: {
      marginRight: size.spacing["8"],
      color: color.text.neutral.strong[mode],
    },
    side_right_width: {},
    item: {
      ...root,
      ..._ghost,
      ..._small,
      fontWeight: font.weight.medium,
      padding: 0,
      marginRight: size.spacing[8],
      color: color.text.neutral.default[mode],
      cursor: "pointer",
      "&:last-child": {
        marginRight: 0,
      },
    },
    item_active: {
      ..._primary,
      backgroundColor: color.surface.accent.active[mode],
    },
    item_prev: {
      ..._secondary,
      marginRight: `${size.spacing[32]} !important`,
      backgroundRepeat: "no-repeat",
      backgroundPosition: "left 50% top 50%",
      backgroundSize: size.spacing[20],
      backgroundImage: svgUri(svgColor(IconArrowBack.data, bgSvgColor)),
    },
    item_next: {
      ..._secondary,
      marginLeft: size.spacing[24],
      backgroundRepeat: "no-repeat",
      backgroundPosition: "left 50% top 50%",
      backgroundSize: size.spacing[20],
      backgroundImage: svgUri(svgColor(IconArrowForward.data, bgSvgColor)),
    },
  };
};
